private function getSharesFolder(Folder $node): array {
	return $this->shareManager->getSharesInFolder(
		$this->userId,
		$node,
		true
	);
}

private function getFolderForPath(?string $path = null): Folder {
	if ($path === null) {
		throw new \InvalidArgumentException('Using uri\'s as scope is not supported, please use a path relative to the search arbiter instead');
	}

	$node = $this->tree->getNodeForPath($path);

	if (!$node instanceof Directory) {
		throw new \InvalidArgumentException('Search is only supported on directories');
	}

	$fileInfo = $node->getFileInfo();

	/** @var Folder */
	return $this->rootFolder->get($fileInfo->getPath());
}

/**
 * Mocks the folder at $path, with its ancestors up to the user root as parents
 */
private function mockFolder(string $path, IMountPoint $mountPoint): Folder&MockObject {
	$parent = $this->mockUserRoot();
	$currentPath = self::USER_ROOT;
	foreach (explode('/', substr($path, strlen(self::USER_ROOT) + 1)) as $name) {
		$currentPath .= '/' . $name;
		$folder = $this->createMock(Folder::class);
		$folder->method('getPath')
			->willReturn($currentPath);
		$folder->method('getParent')
			->willReturn($parent);
		$folder->method('getMountPoint')
			->willReturn($mountPoint);
		$parent = $folder;
	}

	return $folder;
}

private function mockSourceNode(
	IStorage $storage,
	bool $shareable = false,
	bool $deletable = false,
	string $internalPath = 'source.txt',
	?IMountPoint $mountPoint = null,
	?Folder $parent = null,
): FileNode&MockObject {
	$node = $this->createMock(FileNode::class);
	$node->method('getStorage')
		->willReturn($storage);
	$node->method('isShareable')
		->willReturn($shareable);
	$node->method('isDeletable')
		->willReturn($deletable);
	$node->method('getInternalPath')
		->willReturn($internalPath);
	$node->method('getMountPoint')
		->willReturn($mountPoint);
	if ($parent !== null) {
		$node->method('getParent')
			->willReturn($parent);
	}

	return $node;
}

private function getUploadFolder(): Folder {
	if ($this->uploadFolder === null) {
		$path = '/' . $this->uid . '/uploads';
		try {
			$folder = $this->rootFolder->get($path);
			if (!$folder instanceof Folder) {
				throw new \Exception('Upload folder is a file');
			}
			$this->uploadFolder = $folder;
		} catch (NotFoundException $e) {
			$this->uploadFolder = $this->rootFolder->newFolder($path);
		}
	}
	return $this->uploadFolder;
}

